SELECT data ->> '$.commit.collection' AS event, count(*) AS count FROM bluesky GROUP BY event ORDER BY count DESC;
SELECT data ->> '$.commit.collection' AS event, count(*) AS count, count(DISTINCT data ->> '$.did') AS users FROM bluesky WHERE data ->> '$.kind' = 'commit' AND data ->> '$.commit.operation' = 'create' GROUP BY event ORDER BY count DESC;
SELECT data ->> '$.commit.collection' AS event, CAST(strftime('%H', (data ->> '$.time_us') / 1000000, 'unixepoch') AS INTEGER) AS hour_of_day, count(*) AS count FROM bluesky WHERE data ->> '$.kind' = 'commit' AND data ->> '$.commit.operation' = 'create' AND data ->> '$.commit.collection' IN ('app.bsky.feed.post', 'app.bsky.feed.repost', 'app.bsky.feed.like') GROUP BY event, hour_of_day ORDER BY hour_of_day, event;
SELECT data ->> '$.did' AS user_id, strftime('%Y-%m-%d %H:%M:%f', MIN(data ->> '$.time_us') / 1000000.0, 'unixepoch') AS first_post_date FROM bluesky WHERE data ->> '$.kind' = 'commit' AND data ->> '$.commit.operation' = 'create' AND data ->> '$.commit.collection' = 'app.bsky.feed.post' GROUP BY user_id ORDER BY MIN(data ->> '$.time_us') ASC LIMIT 3;
SELECT data ->> '$.did' AS user_id, (MAX(data ->> '$.time_us') - MIN(data ->> '$.time_us')) / 1000 AS activity_span FROM bluesky WHERE data ->> '$.kind' = 'commit' AND data ->> '$.commit.operation' = 'create' AND data ->> '$.commit.collection' = 'app.bsky.feed.post' GROUP BY user_id ORDER BY activity_span DESC LIMIT 3;
